def search_recursively(data_structure, searched_val):
    """
    search recursively for a key in a nested dict
    """
    result = None
    if isinstance(data_structure, dict):
        for key, value in data_structure.items():
            if key == searched_val:
                return value
            result = search_recursively(value, searched_val)
    elif isinstance(data_structure, (list, set, tuple)):
        result_list = [search_recursively(item, searched_val) for item in data_structure]
        result = result_list[0] if len(result_list) > 0 else None
    return result
